function cancelEdit(type){editing[type]=null;$(type==="letters"?"letter-form":"miracle-form").reset();$(type==="letters"?"save-letter":"save-miracle").textContent=type==="letters"?"💌 Guardar carta":"🫙 Guardar bilhetinho";$(type==="letters"?"cancel-letter":"cancel-miracle").hidden=true}
