function render(){renderList("letters");renderList("miracles");var total=data.letters.length+data.miracles.length;$("count-letters").textContent="💌 "+data.letters.length+" cartas";$("count-miracles").textContent="🫙 "+data.miracles.length+" gratidões";$("count-leaves").textContent="🌿 "+Math.min(36,total)+" folhas";var count=Math.min(36,total),leaves=$("tree-leaves");leaves.textContent="";var ns="http://www.w3.org/2000/svg";for(var i=0;i<count;i++){var angle=i*2.3999632297,r=18+Math.sqrt((i+1)/36)*91,cx=196+Math.cos(angle)*r*1.12,cy=148+Math.sin(angle)*r*.72;var leaf=document.createElementNS(ns,"ellipse");leaf.setAttribute("cx",cx.toFixed(1));leaf.setAttribute("cy",cy.toFixed(1));leaf.setAttribute("rx",i%5===0?"15":"18");leaf.setAttribute("ry","10");leaf.setAttribute("transform","rotate("+((i*47)%160-80)+" "+cx+" "+cy+")");leaf.setAttribute("fill",["#9fbea1","#bed2b2","#e0acbd","#b3caa5","#edc6d0"][i%5]);leaves.appendChild(leaf)}$("tree-caption").textContent=total===0?"Seu jardim está começando. Cada gratidão fará nascer uma folha. 🌱":total<8?"Seu jardim está florescendo. Continue cultivando suas memórias. 🌿":"Olhe quantas lembranças preciosas já floresceram! 🌸";$("tree").setAttribute("aria-label","Árvore da fé com "+count+" folhas simbólicas")}
